// 3. 실시간 알림 토스트 (100+ 전국 실시간 소셜 프루프)
(function initLiveSocialProof() {
  const toast = document.getElementById('liveToast');
  const msgEl = document.getElementById('toastMessage');
  const timeEl = document.getElementById('toastTime');
  if (!toast || !msgEl || !timeEl) return;

  let toastIdx = 0;
  const shuffledReviews = [...REVIEWS_100].sort(() => Math.random() - 0.5);

  function showNext() {
    const item = shuffledReviews[toastIdx];
    toastIdx = (toastIdx + 1) % shuffledReviews.length;

    const shortName = item.name.split(' ')[0];
    const timeText = (toastIdx % 3 === 0) ? '방금 전' : `${(toastIdx % 4) + 1}분 전`;

    msgEl.innerHTML = `${item.loc} ${shortName}님이 <strong>'${item.report}'</strong>을 확인하셨습니다.`;
    timeEl.textContent = timeText;

    toast.classList.add('show');
    setTimeout(() => {
      toast.classList.remove('show');
    }, 4500);
  }

  setTimeout(showNext, 2500);
  setInterval(showNext, 11000);
})();

// ==========================================================================
// 4. 화면 전환 매니저 (SPA View Switcher)
// ==========================================================================
let currentView = 'landing';

function switchView(viewName) {
  currentView = viewName;
  const views = ['landing', 'input', 'result', 'report'];

  views.forEach(v => {
    const el = document.getElementById(`${v}View`);
    if (el) {
      if (v === viewName) {
        el.classList.remove('hidden');
        el.classList.add('active');
      } else {
        el.classList.add('hidden');
        el.classList.remove('active');
      }
    }
  });

  // 모바일 하단 플로팅 바 제어 (결과 및 리포트 화면에서는 감춤)
  const stickyBar = document.getElementById('mobileStickyBar');
  if (stickyBar) {
    if (viewName === 'result' || viewName === 'report') {
      stickyBar.style.display = 'none';
    } else {
      stickyBar.style.display = '';
    }
  }

  // 리포트 열람 뷰 진입 시 방해되는 토스트 및 긴급 배너 자동 은닉
  document.body.classList.toggle('in-report-view', viewName === 'report');
  const liveToast = document.getElementById('liveToast');
  if (liveToast) liveToast.style.display = (viewName === 'report') ? 'none' : '';
  const urgencyBanner = document.getElementById('urgencyBanner');
  if (urgencyBanner) urgencyBanner.style.display = (viewName === 'report') ? 'none' : '';

  window.scrollTo({ top: 0, behavior: 'smooth' });
}

