// 십신(十神) 산출 함수
function getTenGod(dayStemIdx, otherStemIdx) {
  if (dayStemIdx === otherStemIdx) return "비견";
  const dayEl = CHEONGAN_ELEMENTS_IDX[dayStemIdx];
  const otherEl = CHEONGAN_ELEMENTS_IDX[otherStemIdx];
  const relation = (otherEl - dayEl + 5) % 5;
  const samePolarity = (dayStemIdx % 2) === (otherStemIdx % 2);
  const pairs = {
    0: ["비견", "겁재"],
    1: ["식신", "상관"],
    2: ["편재", "정재"],
    3: ["편관", "정관"],
    4: ["편인", "정인"]
  };
  return pairs[relation][samePolarity ? 0 : 1];
}

