// ==========================================================================
// 5. 정밀 천문 만세력 계산 (lunar-javascript 정밀 24절기 & 시차 보정)
// ==========================================================================

function calculateAstronomicalPillars(year, month, day, timeStr, calendarType) {
  let hour = 12;
  let minute = 0;
  let isTimeUnknown = (timeStr === 'unknown');

  if (!isTimeUnknown && timeStr) {
    const timeBranches = {
      '23:30-01:29': { h: 0, m: 30 },
      '01:30-03:29': { h: 2, m: 30 },
      '03:30-05:29': { h: 4, m: 30 },
      '05:30-07:29': { h: 6, m: 30 },
      '07:30-09:29': { h: 8, m: 30 },
      '09:30-11:29': { h: 10, m: 30 },
      '11:30-13:29': { h: 12, m: 30 },
      '13:30-15:29': { h: 14, m: 30 },
      '15:30-17:29': { h: 16, m: 30 },
      '17:30-19:29': { h: 18, m: 30 },
      '19:30-21:29': { h: 20, m: 30 },
      '21:30-23:29': { h: 22, m: 30 }
    };
    if (timeBranches[timeStr]) {
      hour = timeBranches[timeStr].h;
      minute = timeBranches[timeStr].m;
    }
  }

  let solar, lunar;
  if (typeof Lunar !== 'undefined' && typeof Solar !== 'undefined') {
    if (calendarType === 'lunar') {
      lunar = Lunar.fromYmdHms(year, month, day, hour, minute, 0);
      solar = lunar.getSolar();
    } else if (calendarType === 'lunar_leap') {
      lunar = Lunar.fromYmdHms(year, -month, day, hour, minute, 0);
      solar = lunar.getSolar();
    } else {
      solar = Solar.fromYmdHms(year, month, day, hour, minute, 0);
      lunar = solar.getLunar();
    }

    const ec = lunar.getEightChar();
    const yearStemIdx = CHEONGAN_HANJA.indexOf(ec.getYearGan());
    const yearBranchIdx = JIJI_HANJA.indexOf(ec.getYearZhi());
    const monthStemIdx = CHEONGAN_HANJA.indexOf(ec.getMonthGan());
    const monthBranchIdx = JIJI_HANJA.indexOf(ec.getMonthZhi());
    const dayStemIdx = CHEONGAN_HANJA.indexOf(ec.getDayGan());
    const dayBranchIdx = JIJI_HANJA.indexOf(ec.getDayZhi());

    let hourPillar = null;
    if (!isTimeUnknown) {
      const hourStemIdx = CHEONGAN_HANJA.indexOf(ec.getTimeGan());
      const hourBranchIdx = JIJI_HANJA.indexOf(ec.getTimeZhi());
      hourPillar = { stemIdx: hourStemIdx, branchIdx: hourBranchIdx };
    }

    return {
      solar,
      lunar,
      ec,
      isTimeUnknown,
      yearPillar: { stemIdx: yearStemIdx, branchIdx: yearBranchIdx },
      monthPillar: { stemIdx: monthStemIdx, branchIdx: monthBranchIdx },
      dayPillar: { stemIdx: dayStemIdx, branchIdx: dayBranchIdx },
      hourPillar
    };
  }

  // Fallback if library fails
  let sexagenary = (day + 49) % 60;
  return {
    solar: null,
    lunar: null,
    ec: null,
    isTimeUnknown,
    yearPillar: { stemIdx: (year - 4) % 10, branchIdx: (year - 4) % 12 },
    monthPillar: { stemIdx: 0, branchIdx: (month + 1) % 12 },
    dayPillar: { stemIdx: sexagenary % 10, branchIdx: sexagenary % 12 },
    hourPillar: isTimeUnknown ? null : { stemIdx: 0, branchIdx: 5 }
  };
}

// 기존 인터페이스 호환용 래퍼 함수들
function getDayPillarIndex(year, month, day) {
  const astro = calculateAstronomicalPillars(year, month, day, '12:00', 'solar');
  return astro.dayPillar;
}
function getYearPillarIndex(year) {
  const astro = calculateAstronomicalPillars(year, 7, 15, '12:00', 'solar');
  return astro.yearPillar;
}
function getMonthPillarIndex(yearStemIdx, month) {
  const astro = calculateAstronomicalPillars(1996, month, 15, '12:00', 'solar');
  return astro.monthPillar;
}
function getHourPillarIndex(dayStemIdx, timeStr) {
  const astro = calculateAstronomicalPillars(1996, 7, 15, timeStr, 'solar');
  return astro.hourPillar;
}

