// 6. [궁통보감 조후 120종] 정밀 고전 문헌 연동 총평
// ==========================================================================

function getClimateCritique(dayStemIdx, monthBranchIdx) {
  if (typeof get120ClimateRule === 'function') {
    const rule = get120ClimateRule(dayStemIdx, monthBranchIdx);
    return {
      season: rule.season,
      seasonKorean: rule.branchName,
      seasonBadgeText: rule.seasonBadge,
      quote: rule.critique,
      classicalQuote: rule.passage,
      sourceQuote: rule.sourceQuote,
      anchor: rule.anchor,
      requiredStems: rule.requiredStems || [],
      caution: rule.caution || '',
      ruleId: rule.id
    };
  }

  // Fallback
  const monthHanja = JIJI_HANJA[monthBranchIdx] || '寅';
  const stemHanja = CHEONGAN_HANJA[dayStemIdx] || '甲';
  return {
    season: 'spring',
    seasonKorean: '봄',
    seasonBadgeText: `${monthHanja}월의 ${stemHanja}`,
    quote: "사주의 조후와 계절적 균형을 바로잡아 중화(中和)를 이룰 때 비로소 잠재력이 폭발합니다.",
    classicalQuote: "窮通寶鑑 원전 조후",
    sourceQuote: "調候中和",
    anchor: "",
    requiredStems: [],
    caution: "",
    ruleId: "CL-FALLBACK"
  };
}

// 신강(身强) / 신약(身弱) / 중화(中和) 정밀 평가 알고리즘
function assessSajuStrength(dayPillar, monthPillar, yearPillar, hourPillar) {
  const dayMaster = dayPillar.stemIdx;
  const dayMasterEl = CHEONGAN_ELEMENTS_IDX[dayMaster];
  const resourceEl = (dayMasterEl + 4) % 5; // 나를 생하는 오행 (인성)
  const isHelperEl = (elIdx) => elIdx === dayMasterEl || elIdx === resourceEl;

  let score = 0;

  // 1. 득령(得令, 월지) - 사주 에너지의 35%
  const monthBranchEl = JIJI_ELEMENTS_IDX[monthPillar.branchIdx];
  if (isHelperEl(monthBranchEl)) score += 35;

  // 2. 득지(得地, 일지) - 사주 에너지의 20%
  const dayBranchEl = JIJI_ELEMENTS_IDX[dayPillar.branchIdx];
  if (isHelperEl(dayBranchEl)) score += 20;

  // 3. 득세(得勢, 타 기둥 천간/지지)
  const checkHelper = (stemIdx, branchIdx, sVal, bVal) => {
    let s = 0;
    if (stemIdx !== null && isHelperEl(CHEONGAN_ELEMENTS_IDX[stemIdx])) s += sVal;
    if (branchIdx !== null && isHelperEl(JIJI_ELEMENTS_IDX[branchIdx])) s += bVal;
    return s;
  };

  score += checkHelper(monthPillar.stemIdx, null, 12, 0); // 월간
  score += checkHelper(yearPillar.stemIdx, yearPillar.branchIdx, 10, 11); // 연주

  if (hourPillar) {
    score += checkHelper(hourPillar.stemIdx, hourPillar.branchIdx, 11, 11); // 시주
  } else {
    score = Math.round(score * 1.25); // 시주 미입력 시 비례 보정
  }

  let status = 'balance';
  let badgeClass = 'balance';
  let title = '중화(中和) 사주';
  let icon = 'fa-scale-balanced';
  let desc = '어느 한쪽으로 치우치지 않고 균형을 갖춘 사주입니다. 환경에 유연하게 적응하나, 결정적 한 방의 추진력과 결단이 성공의 열쇠입니다.';

  if (score >= 48) {
    status = 'strong';
    badgeClass = 'strong';
    title = '신강(身强) 사주';
    icon = 'fa-fire';
    desc = '내면의 에너지가 넘쳐흘러 스스로 깃발을 꽂고 주도해야 직성이 풀리는 자수성가형 기운입니다. 설기(표출)와 나눔이 곧 재물이 됩니다.';
  } else if (score <= 35) {
    status = 'weak';
    badgeClass = 'weak';
    title = '신약(身弱) 사주';
    icon = 'fa-seedling';
    desc = '주변의 기운을 예민하게 읽어내는 전략가 기운입니다. 혼자 맨땅에 헤딩하기보다 든든한 조력자와 시스템을 탈 때 폭발합니다.';
  }

  return { score, status, badgeClass, title, icon, desc };
}

// 특수 지지 관계(원진살, 귀문관살, 칠충, 육합) 정밀 감정
function detectBranchRelations(targetPillarKey, pillars) {
  const targetP = pillars[targetPillarKey];
  if (!targetP) return null;

  const bTarget = targetP.branchIdx;
  const relations = [];
  const otherKeys = ['year', 'month', 'day', 'hour'].filter(k => k !== targetPillarKey && pillars[k]);

  for (const k of otherKeys) {
    const bOther = pillars[k].branchIdx;
    const pair = [bTarget, bOther].sort((a, b) => a - b);
    const keyPair = `${pair[0]}-${pair[1]}`;
    const pName = { year: '연지', month: '월지', day: '일지', hour: '시지' }[k];

    // 원진살 (子未, 丑午, 寅酉, 卯申, 辰亥, 巳戌)
    const WONJIN = ['0-7', '1-6', '2-9', '3-8', '4-11', '5-10'];
    if (WONJIN.includes(keyPair)) {
      relations.push({
        name: '원진살 (怨嗔煞)',
        type: 'warning',
        title: `${pName}와의 원진살(怨嗔煞) 감지`,
        desc: `이 기둥과 ${pName} 사이에 까닭 모를 애증과 서운함이 교차하는 원진살의 기운이 걸려 있습니다. 가까울수록 섭섭함이 쌓이고 뒤돌아서면 칼을 품게 되니, 감정의 완급 조절이 필수적입니다.`
      });
    }

    // 귀문관살 (子酉, 丑午, 寅未, 卯申, 辰亥, 巳戌)
    const GWIMUN = ['0-9', '1-6', '2-7', '3-8', '4-11', '5-10'];
    if (GWIMUN.includes(keyPair)) {
      relations.push({
        name: '귀문관살 (鬼門關煞)',
        type: 'special',
        title: `${pName}와의 귀문관살(鬼門關煞) 감지`,
        desc: `이 기둥에 비범한 천재성과 영적인 직관을 주는 귀문관살이 얽혀 있습니다. 남들이 보지 못하는 이면을 꿰뚫으나, 밤마다 꼬리를 무는 번민과 신경증을 다스려야 대업을 이룹니다.`
      });
    }

    // 칠충 (子午, 丑未, 寅申, 卯酉, 辰戌, 巳亥)
    const CHUNG = ['0-6', '1-7', '2-8', '3-9', '4-10', '5-11'];
    if (CHUNG.includes(keyPair)) {
      relations.push({
        name: '칠충 (七沖)',
        type: 'warning',
        title: `${pName}와의 정면 충돌(沖) 감지`,
        desc: `이 기둥과 ${pName} 사이에 강력한 충(沖)의 불꽃이 튑니다. 정체된 현실을 뒤엎고 새 판을 짜는 폭발적인 변화의 동력이 되지만, 성급한 충동으로 인한 손재수를 각별히 경계해야 합니다.`
      });
    }

    // 육합 (子丑, 寅亥, 卯戌, 辰酉, 巳申, 午未)
    const YUKHAP = ['0-1', '2-11', '3-10', '4-9', '5-8', '6-7'];
    if (YUKHAP.includes(keyPair)) {
      relations.push({
        name: '육합 (六合)',
        type: 'benefit',
        title: `${pName}와의 단단한 육합(六合) 감지`,
        desc: `이 기둥과 ${pName}가 끈끈한 결속을 이루어 흩어진 기운을 하나로 모아줍니다. 어떤 위기에서도 내 편이 되어주는 은밀한 조력자가 인생에 존재함을 의미합니다.`
      });
    }
  }

  return relations.length > 0 ? relations[0] : null;
}

// ==========================================================================
// 6-1. 정통 신살(神煞) & 격국(格局) & 용신(用神) 핵심 알고리즘
// ==========================================================================

// 기둥별 개별 신살 추출 로직 (일간/월지 기준 정밀 보정)
function extractShinsal(pillarType, stemIdx, branchIdx, dayMasterStemIdx = null, monthBranchIdx = null) {
  const shinsals = [];
  const b = branchIdx;
  const s = stemIdx;
  const dStem = (dayMasterStemIdx !== null) ? dayMasterStemIdx : s;

  // 1. 도화살 (자오묘유)
  if ([0, 3, 6, 9].includes(b)) {
    shinsals.push({ name: '도화살 (桃花煞)', type: 'warning', icon: 'fa-heart', desc: '이목을 끄는 치명적 매력과 대중적 인기, 구설수의 양날의 검' });
  }

  // 2. 역마살 (인신사해)
  if ([2, 5, 8, 11].includes(b)) {
    shinsals.push({ name: '역마살 (驛馬煞)', type: 'dynamic', icon: 'fa-horse', desc: '한곳에 묶이지 않고 광활한 무대를 누비며 개척하는 글로벌 추진력' });
  }

  // 3. 화개살 (진술축미)
  if ([1, 4, 7, 10].includes(b)) {
    shinsals.push({ name: '화개살 (華蓋煞)', type: 'benefit', icon: 'fa-scroll', desc: '고독 속에서 만개하는 천재적 예술성과 학문, 명예의 표상' });
  }

  // 4. 백호대살 (7대 백호: 甲辰, 乙未, 丙戌, 丁丑, 戊辰, 壬戌, 癸丑)
  const isBaekho = (s === 0 && b === 4) || (s === 1 && b === 7) || (s === 2 && b === 10) || 
                   (s === 3 && b === 1) || (s === 4 && b === 4) || (s === 8 && b === 10) || (s === 9 && b === 1);
  if (isBaekho) {
    shinsals.push({ name: '백호대살 (白虎大煞)', type: 'warning', icon: 'fa-bolt', desc: '위기 순간에 피를 끓게 만드는 폭발적인 돌파력과 승부욕' });
  }

  // 5. 괴강살 (4대 괴강: 戊戌, 庚辰, 庚戌, 壬辰)
  const isGoegang = (s === 4 && b === 10) || (s === 6 && b === 4) || (s === 6 && b === 10) || (s === 8 && b === 4);
  if (isGoegang) {
    shinsals.push({ name: '괴강살 (魁罡煞)', type: 'warning', icon: 'fa-crown', desc: '만인을 복종시키는 극강의 총명함과 타협 없는 제왕적 카리스마' });
  }

  // 6. 천을귀인 (天乙貴人 - 일간 기준)
  const cheoneulMap = {
    0: [1, 7], 4: [1, 7], 6: [1, 7], // 甲戊庚 -> 丑未
    1: [0, 8], 5: [0, 8],             // 乙己 -> 子申
    2: [9, 11], 3: [9, 11],           // 丙丁 -> 酉亥
    7: [2, 6],                        // 辛 -> 寅午
    8: [3, 5], 9: [3, 5]              // 壬癸 -> 卯巳
  };
  if (cheoneulMap[dStem] && cheoneulMap[dStem].includes(b)) {
    shinsals.push({ name: '천을귀인 (天乙貴人)', type: 'benefit', icon: 'fa-star', desc: '절체절명의 위기마다 은밀하게 활로를 열어주는 최고의 길신' });
  }

  // 7. 문창귀인 (文昌貴人 - 일간 기준)
  const munchangMap = { 0: 5, 1: 6, 2: 8, 3: 9, 4: 8, 5: 9, 6: 11, 7: 0, 8: 2, 9: 3 };
  if (munchangMap[dStem] === b) {
    shinsals.push({ name: '문창귀인 (文昌貴人)', type: 'benefit', icon: 'fa-pen-nib', desc: '비상한 두뇌 회전과 논리적 문장력, 평생 마르지 않는 학문의 총명함' });
  }

  // 8. 현침살 (懸針煞: 甲, 辛, 卯, 午, 申)
  if ([0, 7].includes(s) || [3, 6, 8].includes(b)) {
    shinsals.push({ name: '현침살 (懸針煞)', type: 'special', icon: 'fa-needle', desc: '바늘처럼 정밀하고 예리한 감각으로 전문 기술 및 IT·의료에 탁월함' });
  }

  if (shinsals.length === 0) {
    shinsals.push({ name: '월덕귀인 (月德貴人)', type: 'benefit', icon: 'fa-sun', desc: '흉한 기운을 길함으로 바꾸고 복록을 더하는 온화한 기운' });
  }

  return shinsals;
}

// 자평진전(子平眞詮) 원전 기반 10대 격국 판정 함수
function determineSajuPattern(dayMaster, monthBranchIdx, stems) {
  const hidden = HIDDEN_STEMS_FULL[monthBranchIdx];
  if (!hidden) return SAJU_PATTERNS['정관격'];

  const candidateStems = stems.filter(s => s !== null && s !== undefined);

  // 1. 월지 지장간 투간(透干) 여부 확인 (본기 > 중기 > 여기 순)
  let pickedStem = null;
  if (candidateStems.includes(hidden.main)) {
    pickedStem = hidden.main;
  } else if (hidden.mid !== null && candidateStems.includes(hidden.mid)) {
    pickedStem = hidden.mid;
  } else if (hidden.sub !== null && candidateStems.includes(hidden.sub)) {
    pickedStem = hidden.sub;
  } else {
    // 투간된 지장간이 없으면 월지 본기(정기) 취격
    pickedStem = hidden.main;
  }

  // 2. 비견/겁재일 경우 건록격(建祿格) / 양인격(羊刃格) 특별 판정
  const dayEl = CHEONGAN_ELEMENTS_IDX[dayMaster];
  const pickedEl = CHEONGAN_ELEMENTS_IDX[pickedStem];

  if (dayEl === pickedEl) {
    // 록(祿) 지지 매핑: 甲-寅, 乙-卯, 丙/戊-巳, 丁/己-午, 庚-申, 辛-酉, 壬-亥, 癸-子
    const ROK_PAIRS = { 0: 2, 1: 3, 2: 5, 3: 6, 4: 5, 5: 6, 6: 8, 7: 9, 8: 11, 9: 0 };
    // 양인(羊刃) 지지 매핑: 甲-卯, 丙/戊-午, 庚-酉, 壬-子
    const IN_PAIRS = { 0: 3, 2: 6, 4: 6, 6: 9, 8: 0 };

    if (IN_PAIRS[dayMaster] === monthBranchIdx) {
      return SAJU_PATTERNS['양인격'];
    }
    if (ROK_PAIRS[dayMaster] === monthBranchIdx) {
      return SAJU_PATTERNS['건록격'];
    }
    return SAJU_PATTERNS['건록격'];
  }

  // 3. 8정격 판정
  const tg = getTenGod(dayMaster, pickedStem);
  const map = {
    '정관': '정관격',
    '편관': '칠살격',
    '정인': '정인격',
    '편인': '편인격',
    '식신': '식신격',
    '상관': '상관격',
    '정재': '정재격',
    '편재': '편재격'
  };

  const patternKey = map[tg] || '정관격';
  return SAJU_PATTERNS[patternKey];
}

// 사주 전체 기둥의 종합 신살(神煞) 분석
function calculateExtendedShinsal(dayStem, monthBranch, pillars) {
  const list = [];
  const pKeys = ['year', 'month', 'day', 'hour'];
  const pNames = { year: '연주', month: '월주', day: '일주', hour: '시주' };

  // 천을귀인
  const cheoneulMap = {
    0: [1, 7], 4: [1, 7], 6: [1, 7],
    1: [0, 8], 5: [0, 8],
    2: [9, 11], 3: [9, 11],
    7: [2, 6],
    8: [3, 5], 9: [3, 5]
  };
  const cBranches = cheoneulMap[dayStem] || [];

  // 문창귀인
  const munchangMap = { 0: 5, 1: 6, 2: 8, 3: 9, 4: 8, 5: 9, 6: 11, 7: 0, 8: 2, 9: 3 };
  const mcBranch = munchangMap[dayStem];

  pKeys.forEach(k => {
    const p = pillars[k];
    if (!p) return;
    const name = pNames[k];

    // 천을귀인 감지
    if (cBranches.includes(p.branchIdx)) {
      list.push({
        name: `천을귀인 (${name} 지지)`,
        type: 'benefit',
        icon: 'fa-star',
        desc: `${name}에 천을귀인이 임하여 위급한 순간마다 귀인의 조력과 전화위복의 기적이 따릅니다.`
      });
    }

    // 문창귀인 감지
    if (mcBranch === p.branchIdx) {
      list.push({
        name: `문창귀인 (${name} 지지)`,
        type: 'benefit',
        icon: 'fa-pen-nib',
        desc: `${name}에 문창귀인이 깃들어 총명한 두뇌와 뛰어난 문장력, 전문 지식을 장악합니다.`
      });
    }

    // 백호대살 감지
    const isBaekho = (p.stemIdx === 0 && p.branchIdx === 4) || (p.stemIdx === 1 && p.branchIdx === 7) ||
                     (p.stemIdx === 2 && p.branchIdx === 10) || (p.stemIdx === 3 && p.branchIdx === 1) ||
                     (p.stemIdx === 4 && p.branchIdx === 4) || (p.stemIdx === 8 && p.branchIdx === 10) ||
                     (p.stemIdx === 9 && p.branchIdx === 1);
    if (isBaekho) {
      list.push({
        name: `백호대살 (${name})`,
        type: 'warning',
        icon: 'fa-bolt',
        desc: `${name}에 백호대살이 자리하여 위기 상황에서 물러서지 않는 초인적 담력과 추진력을 발휘합니다.`
      });
    }

    // 괴강살 감지
    const isGoegang = (p.stemIdx === 4 && p.branchIdx === 10) || (p.stemIdx === 6 && p.branchIdx === 4) ||
                      (p.stemIdx === 6 && p.branchIdx === 10) || (p.stemIdx === 8 && p.branchIdx === 4);
    if (isGoegang) {
      list.push({
        name: `괴강살 (${name})`,
        type: 'warning',
        icon: 'fa-crown',
        desc: `${name}에 괴강이 머물러 남에게 지배당하지 않는 총명함과 극단적 카리스마를 선사합니다.`
      });
    }
  });

  return list;
}

// 천간 합충 및 지지 삼합·육합 역학 종합 분석
function analyzeStemBranchDynamics(pillars) {
  const results = { stemComb: [], stemClash: [], branchComb: [], branchClash: [] };
  const pList = ['year', 'month', 'day', 'hour'].map(k => pillars[k]).filter(Boolean);

  // 천간오합 (甲己 합토, 乙庚 합금, 丙辛 합수, 丁壬 합목, 戊癸 합화)
  const stems = pList.map(p => p.stemIdx);
  const stemPairs = [
    { a: 0, b: 5, name: '甲己 合土 (중정지합)', desc: '마음이 넓고 신의가 두터우며 타인에게 신뢰를 주는 결속' },
    { a: 1, b: 6, name: '乙庚 合金 (인의지합)', desc: '의리가 있고 과감한 결단력으로 결과를 쟁취하는 결속' },
    { a: 2, b: 7, name: '丙辛 合水 (위엄지합)', desc: '지혜가 비상하고 냉철한 직관으로 판을 꿰뚫는 결속' },
    { a: 3, b: 8, name: '丁壬 合木 (인수지합)', desc: '온화하고 창의적이며 사람의 마음을 끄는 은밀한 결속' },
    { a: 4, b: 9, name: '戊癸 合火 (무정지합)', desc: '열정과 지성이 결합하여 순간적인 돌파력을 발휘하는 결속' }
  ];
  stemPairs.forEach(pair => {
    if (stems.includes(pair.a) && stems.includes(pair.b)) {
      results.stemComb.push(pair);
    }
  });

  return results;
}

// 억부 & 조후 종합 용신(用神) / 희신(喜神) 도출
function determineYongshin(strength, dayMaster, monthBranchIdx, climate) {
  const dayElIdx = CHEONGAN_ELEMENTS_IDX[dayMaster];
  const isStrong = (strength.status === 'strong');
  const isWeak = (strength.status === 'weak');

  const elNames = ['목(木)', '화(火)', '토(土)', '금(金)', '수(水)'];
  let eokbuYongshin = '';
  let eokbuDesc = '';

  if (isStrong) {
    // 신강: 식상(설기), 재성(소모), 관성(극제)
    const outputEl = (dayElIdx + 1) % 5;
    const wealthEl = (dayElIdx + 2) % 5;
    eokbuYongshin = `${elNames[outputEl]} 식상 및 ${elNames[wealthEl]} 재성`;
    eokbuDesc = `일간의 넘치는 에너지를 밖으로 표출하고 실질적인 부의 자산으로 결실을 맺는 것이 최상의 개운법입니다.`;
  } else if (isWeak) {
    // 신약: 인성(생조), 비겁(방조)
    const resourceEl = (dayElIdx + 4) % 5;
    const peerEl = dayElIdx;
    eokbuYongshin = `${elNames[resourceEl]} 인성 및 ${elNames[peerEl]} 비겁`;
    eokbuDesc = `자신의 에너지를 아끼고, 공인된 지식·자격과 믿을 수 있는 멘토·파트너 시스템을 등 뒤에 업을 때 만개합니다.`;
  } else {
    eokbuYongshin = `중화 오행 (식상·재성 조화)`;
    eokbuDesc = `오행의 편중이 적어 어떤 환경에서도 유연하게 적응하나, 뚜렷한 목표 의식과 결단이 성공의 방아쇠가 됩니다.`;
  }

  const johuText = (climate.requiredStems && climate.requiredStems.length > 0)
    ? climate.requiredStems.join(', ')
    : '계절적 중화 글자';

  return {
    eokbuYongshin,
    eokbuDesc,
    johuYongshin: johuText,
    johuQuote: climate.quote
  };
}

function generatePillarCritique(pillarKey, stemIdx, branchIdx, userName, climateQuote) {
  const topEl = CHEONGAN_ELEMENTS[stemIdx];
  const btmEl = JIJI_ELEMENTS[branchIdx];
  const hanjaPair = `${CHEONGAN_HANJA[stemIdx]}${JIJI_HANJA[branchIdx]}`;
  const koreanPair = `${CHEONGAN[stemIdx]}${JIJI[branchIdx]}`;
  const animal = JIJI_ANIMALS[branchIdx];

  const critiques = {
    day: {
      title: `${hanjaPair} (${koreanPair}일주) - ${animal}의 기운`,
      badge: '일주 (日柱) · 나 자신의 숨겨진 본질',
      quote: `"${climateQuote || '스스로에게는 관대하고 남의 잘못에는 엄격한 이중잣대를 경계해야 대성합니다.'}"`,
      weapon: `위기 상황에서 동물적인 감각으로 활로를 뚫는 승부사 기질.`,
      flaw: `시작은 거창하나 마무리가 흐지부지되는 뒷심 부족.`
    },
    month: {
      title: `${hanjaPair} (${koreanPair}월주) - 사회적 그릇과 환경`,
      badge: '월주 (月柱) · 직업적 칼날과 사회적 성취',
      quote: `"실력과 아이디어는 차고 넘치나, 조직의 룰에 굽히지 못하는 독선이 결정적 승진과 계약의 문턱을 가로막고 있습니다."`,
      weapon: `복잡한 난제를 악바리처럼 파고들어 결과를 만들어내는 실무 돌파력.`,
      flaw: `판이 뜻대로 안 풀리면 욱하고 판을 엎어버리는 충동성.`
    },
    hour: {
      title: `${hanjaPair} (${koreanPair}시주) - 인생 후반과 숨은 야망`,
      badge: '시주 (時柱) · 말년의 부귀와 속마음',
      quote: `"남들 앞에서는 소탈한 척하지만, 실은 단 1원도 손해 보지 않으려는 가장 지독한 현실적 통제권을 쥐고 있습니다."`,
      weapon: `인생 후반으로 갈수록 빛을 발하는 치밀한 자산 관리와 독립심.`,
      flaw: `나이가 들수록 고집이 세져 주변 사람에게 상처를 주는 독선.`
    },
    year: {
      title: `${hanjaPair} (${koreanPair}연주) - 타고난 업보와 뿌리`,
      badge: '연주 (年柱) · 조상의 기운과 타고난 그릇',
      quote: `"뼈대는 비범하게 타고났으나, 초년의 결핍에 갇혀 눈앞의 진짜 기회마저 피해의식으로 흘려보내고 있습니다."`,
      weapon: `어떤 흙탕물에 던져져도 기어이 다시 일어서는 불사조 같은 회복력.`,
      flaw: `과거의 상처에 얽매여 현재의 기회를 의심부터 하는 태도.`
    }
  };

  return critiques[pillarKey] || critiques.day;
}

// ==========================================================================
// 7. 사주 분석 실행 및 결과 렌더링
// ==========================================================================
let currentAnalysisData = null;

function analyzeSaju() {
  const name = document.getElementById('userName').value.trim() || '고객';
  const year = parseInt(document.getElementById('birthYear').value) || 1996;
  const month = parseInt(document.getElementById('birthMonth').value) || 7;
  const day = parseInt(document.getElementById('birthDay').value) || 15;
  const timeStr = document.getElementById('birthTime').value;
  const gender = document.querySelector('input[name="gender"]:checked')?.value || 'female';
  const calendarType = document.querySelector('input[name="calendarType"]:checked')?.value || 'solar';

  const formEl = document.getElementById('sajuForm');
  const loaderEl = document.getElementById('analysisLoader');
  const progressBar = document.getElementById('progressBar');
  const loaderStatus = document.getElementById('loaderStatus');

  formEl.classList.add('hidden');
  loaderEl.classList.remove('hidden');

  const steps = [
    { text: "천문력 기반 24절기(입춘/절입시각) 및 천간·지지 8글자 정밀 추출 중...", progress: 30 },
    { text: "궁통보감 120종 조후 문헌 및 남여 순행·역행 10년 대운 시차 보정 중...", progress: 65 },
    { text: "천명 AI 촌철살인 명리 독심술과 2026 터닝포인트 작성 완료!", progress: 100 }
  ];

  let stepIdx = 0;
  const interval = setInterval(() => {
    if (stepIdx < steps.length) {
      loaderStatus.textContent = steps[stepIdx].text;
      progressBar.style.width = steps[stepIdx].progress + '%';
      stepIdx++;
    } else {
      clearInterval(interval);
      setTimeout(() => {
        loaderEl.classList.add('hidden');
        formEl.classList.remove('hidden');
        
        // 데이터 계산 및 렌더링
        renderFullResult(name, year, month, day, timeStr, gender, calendarType);
        // 화면을 결과 뷰로 전환
        switchView('result');
      }, 400);
    }
  }, 600);
}

// 전체 결과 렌더링 (천문력 정밀 계산 & 궁통보감 120종 조후 연동)
function renderFullResult(name, year, month, day, timeStr, gender = 'female', calendarType = 'solar') {
  const astro = calculateAstronomicalPillars(year, month, day, timeStr, calendarType);
  const enrichPillar = (p) => {
    if (!p) return null;
    return {
      ...p,
      hanja: `${CHEONGAN_HANJA[p.stemIdx]}${JIJI_HANJA[p.branchIdx]}`,
      korean: `${CHEONGAN[p.stemIdx]}${JIJI[p.branchIdx]}`
    };
  };
  const yearPillar = enrichPillar(astro.yearPillar);
  const monthPillar = enrichPillar(astro.monthPillar);
  const dayPillar = enrichPillar(astro.dayPillar);
  const hourPillar = enrichPillar(astro.hourPillar);

  const dayMaster = dayPillar.stemIdx;
  const dayBranch = dayPillar.branchIdx;
  const natureName = `${CHEONGAN_HANJA[dayMaster]}${JIJI_HANJA[dayBranch]} (${CHEONGAN[dayMaster]}${JIJI[dayBranch]}일주)`;

  // 1. 궁통보감 고전 조후 120종 판정
  const climate = getClimateCritique(dayMaster, monthPillar.branchIdx);

  // 2. 신강 / 신약 / 중화 정밀 판정
  const strength = assessSajuStrength(dayPillar, monthPillar, yearPillar, hourPillar);

  // 3. 자평진전 10대 격국(格局) 판정
  const stems = [yearPillar.stemIdx, monthPillar.stemIdx, hourPillar ? hourPillar.stemIdx : null];
  const pattern = determineSajuPattern(dayMaster, monthPillar.branchIdx, stems);

  // 4. 사주 종합 신살(神煞) 스캔
  const extendedShinsal = calculateExtendedShinsal(dayMaster, monthPillar.branchIdx, {
    year: yearPillar,
    month: monthPillar,
    day: dayPillar,
    hour: hourPillar
  });

  // 5. 천간 합충 및 지지 역학 분석
  const dynamics = analyzeStemBranchDynamics({
    year: yearPillar,
    month: monthPillar,
    day: dayPillar,
    hour: hourPillar
  });

  // 6. 억부 & 조후 통합 용신(用神) 판정
  const yongshin = determineYongshin(strength, dayMaster, monthPillar.branchIdx, climate);

  // 7. 10년 대운(大運) 8단계 배열 산출
  const daeunList = [];
  const _SolarRef = (typeof Solar !== 'undefined') ? Solar : (typeof window !== 'undefined' ? window.Solar : null);
  let ecObj = astro.ec;
  if (!ecObj && _SolarRef && year && month && day) {
    try {
      ecObj = _SolarRef.fromYmdHms(year, month, day, 12, 0, 0).getLunar().getEightChar();
    } catch (e) {}
  }
  if (ecObj && typeof ecObj.getYun === 'function') {
    const yun = ecObj.getYun(gender === 'male' ? 1 : 0);
    const dyArr = yun.getDaYun();
    for (let i = 1; i < dyArr.length && daeunList.length < 8; i++) {
      const dy = dyArr[i];
      const gz = dy.getGanZhi();
      if (!gz || gz.length < 2) continue;
      const gIdx = Math.max(0, CHEONGAN_HANJA.indexOf(gz[0]));
      const zIdx = Math.max(0, JIJI_HANJA.indexOf(gz[1]));
      daeunList.push({
        startAge: dy.getStartAge(),
        endAge: dy.getEndAge(),
        startYear: dy.getStartYear(),
        gan: gz[0],
        zhi: gz[1],
        kor: `${CHEONGAN[gIdx]}${JIJI[zIdx]}`,
        tenGod: getTenGod(dayMaster, gIdx)
      });
    }
  }
  while (daeunList.length < 8) {
    const idx = daeunList.length;
    const gIdx = (monthPillar.stemIdx + idx + 1) % 10;
    const zIdx = (monthPillar.branchIdx + idx + 1) % 12;
    daeunList.push({
      startAge: 4 + idx * 10,
      endAge: 13 + idx * 10,
      startYear: year + 4 + idx * 10,
      gan: CHEONGAN_HANJA[gIdx],
      zhi: JIJI_HANJA[zIdx],
      kor: `${CHEONGAN[gIdx]}${JIJI[zIdx]}`,
      tenGod: getTenGod(dayMaster, gIdx)
    });
  }

  currentAnalysisData = {
    name,
    year,
    month,
    day,
    timeStr,
    gender,
    calendarType,
    solar: astro.solar,
    lunar: astro.lunar,
    ec: astro.ec,
    climate,
    strength,
    pattern,
    extendedShinsal,
    dynamics,
    yongshin,
    daeunList,
    pillars: {
      hour: hourPillar,
      day: dayPillar,
      month: monthPillar,
      year: yearPillar
    }
  };

  // 상단 헤더 텍스트 & 정제된 사이다 한줄평
  document.getElementById('resUserTitle').innerHTML = `${name}님의 일주는 <span class="gold-gradient">${natureName}</span>입니다.`;
  document.getElementById('resShortSummary').textContent = climate.quote;

  // 신강/신약 배지 & 계절 배지
  const strengthBadgeEl = document.getElementById('resStrengthBadge');
  if (strengthBadgeEl) {
    strengthBadgeEl.className = `strength-badge ${strength.badgeClass}`;
    strengthBadgeEl.innerHTML = `<i class="fa-solid ${strength.icon}"></i> ${strength.title}`;
  }
  const seasonBadgeEl = document.getElementById('resSeasonBadge');
  if (seasonBadgeEl) {
    const reqText = (climate.requiredStems && climate.requiredStems.length > 0)
      ? ` · 조후희용: ${climate.requiredStems.join(', ')}`
      : '';
    seasonBadgeEl.textContent = `${climate.seasonBadgeText}${reqText}`;
  }

  // 4기둥 인터랙티브 카드 렌더링
  const pillarsGrid = document.getElementById('resultPillars');
  pillarsGrid.innerHTML = '';

  const pillarList = [
    { key: 'hour', label: '시주 (時柱)', sub: '말년 / 자녀', pillar: hourPillar, defaultActive: false },
    { key: 'day', label: '일주 (日柱) · 나', sub: '본성 / 배우자', pillar: dayPillar, defaultActive: true },
    { key: 'month', label: '월주 (月柱)', sub: '청년 / 사회운', pillar: monthPillar, defaultActive: false },
    { key: 'year', label: '연주 (年柱)', sub: '초년 / 근본', pillar: yearPillar, defaultActive: false }
  ];

  pillarList.forEach(item => {
    const card = document.createElement('div');
    card.className = `interactive-pillar-card ${item.defaultActive ? 'active' : ''}`;
    card.id = `pillarCard_${item.key}`;
    card.onclick = () => selectPillar(item.key);

    if (!item.pillar) {
      card.innerHTML = `
        <span class="p-card-tag">${item.label}</span>
        <div class="p-hanja-pair">
          <span class="hanja-txt" style="color: #64748b;">-</span>
          <span class="hanja-txt" style="color: #64748b;">-</span>
        </div>
        <span class="p-meaning">시간 미입력</span>
        <span class="tap-hint"><i class="fa-solid fa-clock"></i> 탭하여 조회</span>
      `;
    } else {
      const topStem = item.pillar.stemIdx;
      const btmBranch = item.pillar.branchIdx;
      const topEl = CHEONGAN_ELEMENTS[topStem];
      const btmEl = JIJI_ELEMENTS[btmBranch];

      // 십신 태그
      const tenGod = item.key === 'day' ? '일원 (나)' : getTenGod(dayMaster, topStem);

      card.innerHTML = `
        <span class="p-card-tag">${item.label}</span>
        <span class="p-tengod-badge">${tenGod}</span>
        <div class="p-hanja-pair">
          <span class="hanja-txt ${topEl}">${CHEONGAN_HANJA[topStem]}</span>
          <span class="hanja-txt ${btmEl}">${JIJI_HANJA[btmBranch]}</span>
        </div>
        <span class="p-meaning">${CHEONGAN[topStem]}${JIJI[btmBranch]} (${item.sub})</span>
        <span class="tap-hint"><i class="fa-solid fa-hand-pointer"></i> 해독 보기</span>
      `;
    }

    pillarsGrid.appendChild(card);
  });

  // 오행 밸런스 계산
  renderElementsDistribution(yearPillar, monthPillar, dayPillar, hourPillar);

  // 기본 활성 기둥: 일주(day) 세부정보 표출
  selectPillar('day');

  // 만세력 기반 리포트별 후킹 멘트 생성 & 장바구니 초기화
  renderReportHooks();
  resetCart();
}

// 특정 기둥 탭 선택 시 실시간 상세정보 갱신
function selectPillar(pillarKey) {
  if (!currentAnalysisData) return;

  // 카드 활성화 스타일 토글
  document.querySelectorAll('.interactive-pillar-card').forEach(el => el.classList.remove('active'));
  const targetCard = document.getElementById(`pillarCard_${pillarKey}`);
  if (targetCard) targetCard.classList.add('active');

  const pData = currentAnalysisData.pillars[pillarKey];
  const detailBox = document.getElementById('pillarDetailBox');

  // 애니메이션 효과
  detailBox.classList.remove('pulse-update');
  void detailBox.offsetWidth; // reflow
  detailBox.classList.add('pulse-update');

  if (!pData) {
    document.getElementById('detailPillarBadge').textContent = '시주 (時柱) · 출생 시간 미입력';
    document.getElementById('detailPillarTitle').textContent = '태어난 시간 정보가 없습니다';
    document.getElementById('detailShinsalTags').innerHTML = `<span class="shinsal-pill warning"><i class="fa-solid fa-circle-question"></i> 삼주 분석 모드</span>`;
    document.getElementById('detailCriticQuote').textContent = '태어난 시간을 모르실 경우 말년운과 자녀운의 정밀 감명이 제한됩니다. 다시 조회를 통해 출생 시간을 입력하시면 숨겨진 시주 신살을 확인하실 수 있습니다.';
    document.getElementById('detailWeaponText').textContent = '일주와 월주를 기반으로 한 사회적 성취 능력';
    document.getElementById('detailFlawText').textContent = '말년의 변수와 숨은 내면 심리의 불확실성';
    document.getElementById('detailRelationBox')?.classList.add('hidden');
    document.getElementById('detailPsychologyBox')?.classList.add('hidden');
    return;
  }

  // 1. 신살 추출
  const dayMaster = currentAnalysisData.pillars.day.stemIdx;
  const monthBranch = currentAnalysisData.pillars.month.branchIdx;
  const shinsals = extractShinsal(pillarKey, pData.stemIdx, pData.branchIdx, dayMaster, monthBranch);

  // 2. 특수 지지 관계(원진살/귀문관살/충/합) 검출
  const relation = detectBranchRelations(pillarKey, currentAnalysisData.pillars);
  const relationBox = document.getElementById('detailRelationBox');
  if (relation) {
    if (relationBox) {
      relationBox.classList.remove('hidden');
      document.getElementById('detailRelationTitle').textContent = relation.title;
      document.getElementById('detailRelationDesc').textContent = relation.desc;
    }
    shinsals.unshift({ name: relation.name, type: relation.type === 'special' ? 'special' : relation.type, icon: 'fa-triangle-exclamation' });
  } else if (relationBox) {
    relationBox.classList.add('hidden');
  }

  // 신살 태그 렌더링
  const tagsHtml = shinsals.map(s => `
    <span class="shinsal-pill ${s.type}">
      <i class="fa-solid ${s.icon}"></i> ${s.name}
    </span>
  `).join('');
  document.getElementById('detailShinsalTags').innerHTML = tagsHtml;

  // 3. 현대적 십신 심리학 해독
  let activeTenGod = '비견';
  if (pillarKey === 'day') {
    // 일주의 경우 일지(지장간 대표)의 십신을 조명
    const hiddenStem = HIDDEN_STEMS[pData.branchIdx][0];
    activeTenGod = getTenGod(dayMaster, hiddenStem);
  } else {
    activeTenGod = getTenGod(dayMaster, pData.stemIdx);
  }

  const psycho = TEN_GOD_PSYCHOLOGY[activeTenGod] || TEN_GOD_PSYCHOLOGY['비견'];
  const psychoBox = document.getElementById('detailPsychologyBox');
  if (psychoBox) {
    psychoBox.classList.remove('hidden');
    document.getElementById('detailPsychologyTitle').innerHTML = `<i class="fa-solid fa-brain"></i> 심리적 본질: ${activeTenGod} (${psycho.badge})`;
    document.getElementById('detailPsychologyDesc').innerHTML = `${psycho.nature} <br><strong style="color: #fca5a5;">주의:</strong> ${psycho.flaw}`;
  }

  // 4. 촌철살인 비평 생성
  const critique = generatePillarCritique(pillarKey, pData.stemIdx, pData.branchIdx, currentAnalysisData.name, currentAnalysisData.climate.quote);
  document.getElementById('detailPillarBadge').textContent = critique.badge;
  document.getElementById('detailPillarTitle').textContent = critique.title;
  document.getElementById('detailCriticQuote').textContent = critique.quote;
  document.getElementById('detailWeaponText').textContent = critique.weapon;
  document.getElementById('detailFlawText').textContent = critique.flaw;
}

// 오행 밸런스 렌더링
function renderElementsDistribution(yearP, monthP, dayP, hourP) {
  const counts = { wood: 0, fire: 0, earth: 0, metal: 0, water: 0 };
  const add = (p) => {
    if (!p) return;
    counts[CHEONGAN_ELEMENTS[p.stemIdx]]++;
    counts[JIJI_ELEMENTS[p.branchIdx]]++;
  };
  add(yearP);
  add(monthP);
  add(dayP);
  add(hourP);

  const total = Object.values(counts).reduce((a, b) => a + b, 0);
  const percents = {
    wood: Math.round((counts.wood / total) * 100),
    fire: Math.round((counts.fire / total) * 100),
    earth: Math.round((counts.earth / total) * 100),
    metal: Math.round((counts.metal / total) * 100),
    water: Math.round((counts.water / total) * 100)
  };

  const container = document.getElementById('elementsBarsContainer');
  const elLabels = { wood: '木 (나무)', fire: '火 (불)', earth: '土 (흙)', metal: '金 (쇠)', water: '水 (물)' };

  container.innerHTML = Object.keys(percents).map(k => `
    <div class="element-bar-row">
      <span class="el-name ${k}">${elLabels[k]}</span>
      <div class="bar-track"><div class="bar-fill ${k}" style="width: ${percents[k]}%"></div></div>
      <span class="el-val">${percents[k]}%</span>
    </div>
  `).join('');

  // 가장 부족한 기운
  const sorted = Object.entries(percents).sort((a, b) => a[1] - b[1]);
  const least = sorted[0][0];
  const adviceNames = {
    wood: '목(木 - 시작/추진력)',
    fire: '화(火 - 열정/표현력)',
    earth: '토(土 - 신뢰/인내심)',
    metal: '금(金 - 결단/마무리 결실)',
    water: '수(水 - 유연함/통찰력)'
  };
  document.getElementById('resElementAdvice').innerHTML = `
    💡 <strong>기운 처방:</strong> 현재 사주에서 <strong>'${adviceNames[least]}'</strong>의 기운이 가장 희소합니다. 시작은 좋아도 마무리가 불안정하거나 결단을 주저하는 원인이 여기에 있으니, 보완 색상과 생활 습관을 실천하시면 묶였던 운의 고리가 풀립니다.
  `;
}

