const ELEMENT_SHORT = { wood: '목(木)', fire: '화(火)', earth: '토(土)', metal: '금(金)', water: '수(水)' };

// 2026년은 병오(丙午)년 — 불(火)의 해. 일간 오행 기준 올해 불 기운이 갖는 의미
const YEAR_2026_BY_DAYMASTER = {
  wood:  '나무가 불을 만나 꽃을 피우는 해입니다. 재능은 터지지만, 너무 태우면 남는 게 재뿐입니다',
  fire:  '불 위에 불이 겹치는 해입니다. 경쟁자와 돈 나갈 일이 동시에 몰려듭니다',
  earth: '불이 흙을 데워주는 해입니다. 문서·계약·자격의 운이 들어오지만 게으름이 그 복을 걷어찹니다',
  metal: '불이 쇠를 녹이는 해입니다. 승진이냐 번아웃이냐, 압박을 어떻게 다루느냐가 갈림길입니다',
  water: '물이 불을 만나 재물(財)로 바뀌는 해입니다. 돈이 들어오는 만큼 빠져나가는 구멍도 큽니다'
};

function renderReportHooks() {
  if (!currentAnalysisData) return;
  const { name, pillars, pattern, strength } = currentAnalysisData;
  const day = pillars.day;
  const dayEl = CHEONGAN_ELEMENTS[day.stemIdx];
  const dayBranch = day.branchIdx;
  const dayPair = `${CHEONGAN[day.stemIdx]}${JIJI[day.branchIdx]}`;

  // 헤더 타이틀
  document.getElementById('checkoutTitle').textContent =
    `"${name}님의 만세력에는 아직 열리지 않은 이야기가 남아 있습니다"`;

  // --- 1) 세운 총운 & 향후 12개월 월별 터닝포인트 후킹 ---
  let branchRelation;
  if (dayBranch === 0) {
    branchRelation = `게다가 일지 자(子)와 세운의 기운이 정면으로 부딪히는 충(沖)의 파장이 걸려 있습니다. 이사·이별·이직 중 하나는 반드시 옵니다.`;
  } else if ([2, 10].includes(dayBranch)) {
    branchRelation = `일지 ${JIJI[dayBranch]}(${JIJI_HANJA[dayBranch]})가 세운과 삼합을 이뤄, 잘만 타면 몇 년 치 운을 향후 12개월 안에 몰아 쓸 수 있습니다.`;
  } else if (dayBranch === 6) {
    branchRelation = `일지에 강한 화(火) 기운이 겹쳐 스스로를 갉아먹는 조급증을 다스려야 하는 시기입니다.`;
  } else {
    branchRelation = `기회가 들어오는 달과 발목 잡히는 달이 뚜렷하게 갈립니다. 향후 12개월 중 그 '결정적 달'이 언제인지가 핵심입니다.`;
  }
  setHook('newyear', `${dayPair}일주에게 지금 흐르는 세운(歲運)은 ${YEAR_2026_BY_DAYMASTER[dayEl]}. ${branchRelation}`);

  // --- 2) 평생 총운 & 의명진단 마스터팩 후킹 ---
  const counts = { wood: 0, fire: 0, earth: 0, metal: 0, water: 0 };
  Object.values(pillars).forEach(p => {
    if (!p) return;
    counts[CHEONGAN_ELEMENTS[p.stemIdx]]++;
    counts[JIJI_ELEMENTS[p.branchIdx]]++;
  });
  const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1]);
  const strongest = sorted[0][0];
  const weakest = sorted[sorted.length - 1][0];
  const missingText = counts[weakest] === 0
    ? `${ELEMENT_SHORT[weakest]}이 아예 비어 있는 사주`
    : `${ELEMENT_SHORT[weakest]}이 극도로 부족한 사주`;
  setHook('master', `${ELEMENT_SHORT[strongest]} 기운이 원국을 장악한 반면, ${missingText}입니다. 이 빈자리가 채워지는 황금 대운과 선천적으로 취약한 오장육부 의명진단(醫命診斷) 처방이 23장에 걸쳐 기록되어 있습니다.`);

  // --- 3) 1:1 심층 궁합 & 성인 속궁합 후킹 ---
  const dayShinsals = extractShinsal('day', day.stemIdx, day.branchIdx).map(s => s.name.split(' ')[0]);
  let loveLine;
  if (dayShinsals.includes('도화살')) {
    loveLine = `배우자 자리에 도화살이 앉아 있습니다. 사람이 끊이지 않는 대신, 정작 '내 사람'을 고르는 눈이 흐려지기 쉬운 구조입니다.`;
  } else if (dayShinsals.includes('역마살')) {
    loveLine = `배우자 자리에 역마살이 들어 있습니다. 붙잡으면 도망가고 놓으면 돌아오는 인연 — 거리와 여행지, 타이밍이 관계의 전부입니다.`;
  } else if (dayShinsals.includes('화개살')) {
    loveLine = `배우자 자리에 화개살이 있습니다. 겉으론 무심해 보여도 밤에는 깊은 정신적·육체적 몰입을 갈구하는 사주입니다.`;
  } else if (dayShinsals.includes('백호대살') || dayShinsals.includes('괴강살')) {
    loveLine = `배우자 자리의 기운이 강하고 날카롭습니다. 약한 상대는 당신을 감당하지 못하고, 센 상대와는 부딪힙니다.`;
  } else {
    loveLine = `배우자 자리(일지)의 ${JIJI[dayBranch]}(${JIJI_HANJA[dayBranch]})는 끌리는 사람과 맞는 사람이 다른 구조입니다.`;
  }
  setHook('match', `${loveLine} 재회든, 짝사랑이든, 현재 연인이든 두 사주의 식궁합·여행지부터 은밀한 19+ 침실 무드·체위까지 낱낱이 파헤칩니다.`);

  // --- 4) 이직 · 취업 · 창업 커리어 천직 비서 후킹 ---
  const patName = pattern ? pattern.name : '정관격';
  const careerLine = (strength && strength.status !== 'weak')
    ? `원국이 ${patName}에 ${strength.title} 구조라 결코 능력이 없어 굶을 팔자가 아닙니다. 이직이라면 지금 우물이 좁아 더 나은 확률을 내다보고 싶은 갈증이고, 취업 준비 중이라면 '못' 가는 게 아니라 눈높이 뒤에 숨어 '안' 가고 있는 건 아닌지 정곡부터 짚어드립니다.`
    : `원국이 ${patName}(${strength ? strength.title : '중화'}) 구조라 남 좋은 일만 시키고 정작 내 몫은 챙기지 못해 속앓이하기 쉽습니다. 이직·취업·내 사업 중 어디에서 내 진짜 몸값이 터지는지 정신과 상담처럼 깊이 파고듭니다.`;
  setHook('career', careerLine);
}

function setHook(key, text) {
  const el = document.querySelector(`#repHook_${key} span`);
  if (el) el.textContent = text;
}

// ==========================================================================
// 9. 리포트 중복 선택 & 묶음 할인 (2개 이상 선택 시 10%)
// ==========================================================================
const REPORT_PRODUCTS = {
  newyear: { title: '세운(歲運) 총운 & 12개월 월별 터닝포인트', price: 22500 },
  master:  { title: '평생 총운 & 10년 대운 · 의명진단 마스터팩', price: 29500 },
  match:   { title: '1:1 심층 사주 궁합', price: 24500 },
  career:  { title: '이직 · 취업 · 창업 커리어 천직 비서', price: 26000 }
};
const BUNDLE_MIN_COUNT = 2;
const BUNDLE_RATE = 0.10;

const selectedReports = new Set();

const won = n => `${n.toLocaleString('ko-KR')}원`;

function calcCart() {
  const items = [...selectedReports].map(k => ({ key: k, ...REPORT_PRODUCTS[k] }));
  const subtotal = items.reduce((sum, i) => sum + i.price, 0);
  // 10원 단위 절사
  const discount = items.length >= BUNDLE_MIN_COUNT ? Math.floor((subtotal * BUNDLE_RATE) / 10) * 10 : 0;
  return { items, subtotal, discount, total: subtotal - discount };
}

function toggleReport(key) {
  if (selectedReports.has(key)) {
    selectedReports.delete(key);
  } else {
    selectedReports.add(key);
  }
  updateCartUI();
}

function resetCart() {
  selectedReports.clear();
  updateCartUI();
}

function updateCartUI() {
  // 카드 체크 상태
  Object.keys(REPORT_PRODUCTS).forEach(k => {
    const card = document.getElementById(`repCard_${k}`);
    if (!card) return;
    const on = selectedReports.has(k);
    card.classList.toggle('active', on);
    card.setAttribute('aria-checked', on ? 'true' : 'false');
  });

  const { items, subtotal, discount, total } = calcCart();

  // 선택 항목 리스트
  const list = document.getElementById('selectedItemsList');
  list.innerHTML = items.length === 0
    ? `<p class="empty-selection">위에서 보고 싶은 리포트를 선택해주세요.</p>`
    : items.map(i => `
        <div class="sum-row item-row">
          <span><i class="fa-solid fa-check"></i> ${i.title}</span>
          <span>${won(i.price)}</span>
        </div>`).join('');

  document.getElementById('subtotalPrice').textContent = won(subtotal);
  document.getElementById('bundleDiscountRow').classList.toggle('hidden', discount === 0);
  document.getElementById('bundleDiscountPrice').textContent = `-${won(discount)}`;
  document.getElementById('selectedReportPrice').textContent = won(total);

  // 묶음 할인 유도 문구
  const nudge = document.getElementById('bundleNudge');
  const remaining = Object.keys(REPORT_PRODUCTS).filter(k => !selectedReports.has(k));
  if (items.length === 0) {
    nudge.innerHTML = `<i class="fa-solid fa-circle-info"></i> <strong>2개 이상</strong> 선택하면 전체 금액에서 <strong>10% 추가 할인</strong>됩니다.`;
    nudge.className = 'bundle-nudge';
  } else if (items.length < BUNDLE_MIN_COUNT) {
    const cheapest = Math.min(...remaining.map(k => REPORT_PRODUCTS[k].price));
    const expectedSave = Math.floor(((subtotal + cheapest) * BUNDLE_RATE) / 10) * 10;
    nudge.innerHTML = `<i class="fa-solid fa-gift"></i> <strong>1개만 더</strong> 선택하면 최대 <strong>${won(expectedSave)}</strong> 추가 할인됩니다.`;
    nudge.className = 'bundle-nudge';
  } else {
    nudge.innerHTML = `<i class="fa-solid fa-circle-check"></i> 묶음 할인 적용! <strong>${won(discount)}</strong>을 아끼셨어요.`;
    nudge.className = 'bundle-nudge applied';
  }

  // 결제 버튼
  const btn = document.getElementById('payButton');
  btn.disabled = items.length === 0;
  document.getElementById('payBtnText').textContent =
    items.length === 0 ? '리포트를 선택해주세요' : `${won(total)} 결제하기`;
}

// 카드 키보드 접근성 (Enter / Space)
document.addEventListener('keydown', e => {
  const card = e.target.closest && e.target.closest('.report-select-card');
  if (card && (e.key === 'Enter' || e.key === ' ')) {
    e.preventDefault();
    card.click();
  }
});

