const PORTONE_CONFIG = {
  // 포트원 관리자 콘솔(https://admin.portone.io) > 결제 연동 > 연동 정보에서 발급받은 Store ID
  storeId: "store-demo-cheonmun-saju",
  // 포트원 관리자 콘솔 > 채널 관리에서 등록한 채널 키 (나이스페이먼츠, KG이니시스, 카카오페이 등)
  channelKey: "channel-key-demo",
  // 테스트 모드 플래그 (실제 키 입력 전까지는 안전하게 테스트 시뮬레이션 지원)
  isTestMode: true
};

let currentSelectedPayMethod = 'CARD';

function selectPayMethod(method, btn) {
  currentSelectedPayMethod = method;
  document.querySelectorAll('.pay-method-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
}

function triggerPayment() {
  const { items, discount, total } = calcCart();
  if (items.length === 0) return;

  const refundCheck = document.getElementById('refundNoticeCheck');
  if (refundCheck && !refundCheck.checked) {
    alert('맞춤형 디지털 콘텐츠 특성상 열람 개시 후 청약철회(환불)가 제한됨에 동의해 주셔야 결제가 가능합니다.');
    refundCheck.focus();
    return;
  }

  document.getElementById('payModalItems').innerHTML = items.map(i => `
    <div class="summary-row">
      <span>${i.title}</span>
      <span>${won(i.price)}</span>
    </div>`).join('');
  document.getElementById('payModalDiscountRow').classList.toggle('hidden', discount === 0);
  document.getElementById('payModalDiscount').textContent = `-${won(discount)}`;
  document.getElementById('payModalTotal').textContent = won(total);
  document.getElementById('payConfirmBtnText').textContent = `${won(total)} 안전 결제하기`;

  document.getElementById('payModal').classList.remove('hidden');
}

function closePayModal() {
  document.getElementById('payModal').classList.add('hidden');
}

async function confirmPayment() {
  const { items, total } = calcCart();
  if (items.length === 0) return;

  const btn = document.querySelector('.btn-portone-confirm') || document.querySelector('.btn-toss-confirm');
  const origText = btn ? btn.innerHTML : '';
  if (btn) {
    btn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> 결제창 연결 중...`;
    btn.disabled = true;
  }

  const orderTitle = items.length === 1 
    ? items[0].title 
    : `${items[0].title} 외 ${items.length - 1}건`;
  const paymentId = `order_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
  const userName = (currentAnalysisData && currentAnalysisData.name) ? currentAnalysisData.name : "익명";

  // 포트원 V2 브라우저 SDK 공식 연동 (실제 storeId가 설정되었을 때 실행)
  if (typeof PortOne !== 'undefined' && PORTONE_CONFIG.storeId && !PORTONE_CONFIG.storeId.includes('demo')) {
    try {
      const paymentParams = {
        storeId: PORTONE_CONFIG.storeId,
        channelKey: PORTONE_CONFIG.channelKey,
        paymentId: paymentId,
        orderName: orderTitle,
        totalAmount: total,
        currency: "KRW",
        customer: {
          fullName: userName
        }
      };

      // 결제 수단별 파라미터 매핑
      if (currentSelectedPayMethod === 'CARD') {
        paymentParams.payMethod = 'CARD';
      } else if (['KAKAOPAY', 'NAVERPAY', 'TOSSPAY'].includes(currentSelectedPayMethod)) {
        paymentParams.payMethod = 'EASY_PAY';
        paymentParams.easyPay = {
          provider: currentSelectedPayMethod
        };
      } else {
        paymentParams.payMethod = 'CARD';
      }

      const response = await PortOne.requestPayment(paymentParams);

      if (response && response.code != null) {
        // 결제 실패 또는 사용자 취소 처리
        if (response.code === 'FAILURE_TYPE_CANCELLED' || (response.message && response.message.includes('취소'))) {
          alert('결제가 취소되었습니다.');
        } else {
          alert(`결제 실패: ${response.message || response.code}`);
        }
        if (btn) { btn.innerHTML = origText; btn.disabled = false; }
        return;
      }

      // 결제 성공 검증 후 리포트 발급
      completePaymentSuccess(btn, origText);
      return;
    } catch (err) {
      console.error('포트원 결제 오류:', err);
      alert('결제창 호출 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.');
      if (btn) { btn.innerHTML = origText; btn.disabled = false; }
      return;
    }
  }

  // PG사 심사 및 승인 전 안내: 무단 열람 차단
  setTimeout(() => {
    if (btn) { btn.innerHTML = origText; btn.disabled = false; }
    closePayModal();
    alert('현재 결제 심사 및 채널 키 연동 대기 중입니다.\n\n결제 전 감명서 양식과 완성본 검수는 화면의 [견본 보기] 버튼을 이용해주세요.');
  }, 600);
}

// 결제 전 결과물 양식/품질 사전 확인용 더미 샘플 리포트 렌더러
function openSampleDummyReport() {
  if (!currentAnalysisData) {
    // 분석 데이터가 없는 경우 기본 임인일주 샘플 프로필 생성
    const astro = calculateAstronomicalPillars(1996, 7, 15, "09:30", "solar");
    const shinsal = calculateExtendedShinsal(astro.dayStem, astro.monthBranch, astro.pillars);
    currentAnalysisData = {
      name: "체험자",
      year: 1996,
      month: 7,
      day: 15,
      timeStr: "09:30",
      gender: "female",
      calendarType: "solar",
      solar: astro.solar,
      lunar: astro.lunar,
      ec: astro.ec,
      pillars: astro.pillars,
      daewoon: astro.daewoon,
      shinsal: shinsal,
      isDummySample: true
    };
  }

  // 4대 리포트 전체를 더미로 세팅
  const allReportKeys = ['newyear', 'master', 'match', 'career'];
  renderPurchasedReportBook(allReportKeys);

  // 상단 툴바 표시를 견본 모드로 안내
  const barUserName = document.getElementById('reportBarUserName');
  if (barUserName) {
    barUserName.innerHTML = `<span style="background:#eab308;color:#000;padding:2px 8px;border-radius:4px;font-size:0.75rem;font-weight:700;margin-right:6px;">견본(SAMPLE)</span> ${currentAnalysisData.name || '체험자'}님의 86p 감명서`;
  }
  const certPill = document.querySelector('.cert-pill');
  if (certPill) {
    certPill.innerHTML = `<i class="fa-solid fa-eye"></i> 견본 미리보기`;
  }

  // 리포트 서책 화면으로 전환
  switchView('report');
}

function completePaymentSuccess(btn, origText) {
  closePayModal();
  if (btn) {
    btn.innerHTML = origText;
    btn.disabled = false;
  }

  // 구매한 리포트 목록
  const purchasedKeys = Array.from(selectedReports);

  // 운명서 서책 렌더링
  renderPurchasedReportBook(purchasedKeys);

  // 리포트 뷰로 화면 전환
  switchView('report');
}

// ==========================================================================
// 10-1. 프리미엄 맞춤 운명서 서책 렌더러 (모바일 퍼스트 UX)
// ==========================================================================
let activeReportTab = null;

function renderPurchasedReportBook(purchasedKeys) {
  if (!currentAnalysisData || purchasedKeys.length === 0) return;

  const user = currentAnalysisData;
  const dayMaster = user.pillars.day.stemIdx;
  const dayBranch = user.pillars.day.branchIdx;
  const natureName = `${CHEONGAN_HANJA[dayMaster]}${JIJI_HANJA[dayBranch]} (${CHEONGAN[dayMaster]}${JIJI[dayBranch]}일주)`;

  // 상단 툴바 정보
  document.getElementById('reportBarUserName').textContent = `${user.name}님의 운명서`;
  document.getElementById('reportRecipient').textContent = `${user.name} 님 惠存 (혜존)`;

  // 주문번호 & 발급일자 생성
  const today = new Date();
  const dateStr = `${today.getFullYear()}. ${String(today.getMonth() + 1).padStart(2, '0')}. ${String(today.getDate()).padStart(2, '0')}`;
  const randomNum = Math.floor(Math.random() * 8999 + 1000);
  document.getElementById('reportOrderId').textContent = `주문번호: ORD-${today.getFullYear()}${String(today.getMonth()+1).padStart(2,'0')}${String(today.getDate()).padStart(2,'0')}-${randomNum}`;
  document.getElementById('reportIssueDate').textContent = `발급일자: ${dateStr}`;

  // 서책 메인 타이틀
  const productTitles = purchasedKeys.map(k => REPORT_PRODUCTS[k].title.replace(/&.*/, '').trim());
  document.getElementById('reportBookTitle').textContent = productTitles.join(' · ');

  // 탭 네비게이션 생성 (구매 항목이 2개 이상일 때)
  const tabsNav = document.getElementById('reportTabsNav');
  const tabIcons = {
    newyear: 'fa-sun',
    master: 'fa-crown',
    match: 'fa-heart',
    career: 'fa-briefcase'
  };
  if (purchasedKeys.length > 1) {
    tabsNav.style.display = 'flex';
    tabsNav.innerHTML = purchasedKeys.map((key, idx) => `
      <button type="button" class="report-tab-btn ${idx === 0 ? 'active' : ''}" id="repTabBtn_${key}" onclick="switchReportTab('${key}')">
        <i class="fa-solid ${tabIcons[key] || 'fa-scroll'}"></i>
        <span>${REPORT_PRODUCTS[key].title}</span>
      </button>
    `).join('');
  } else {
    tabsNav.style.display = 'none';
  }

  // 본문 챕터 렌더링
  const container = document.getElementById('reportChaptersContainer');
  container.innerHTML = '';

  purchasedKeys.forEach((key, idx) => {
    const section = document.createElement('section');
    section.className = `purchased-report-section ${idx === 0 ? 'active' : ''}`;
    section.id = `purchasedSection_${key}`;

    if (key === 'newyear') {
      section.innerHTML = buildNewYearReportHtml(user, natureName);
    } else if (key === 'master') {
      section.innerHTML = buildMasterReportHtml(user, natureName);
    } else if (key === 'match') {
      section.innerHTML = buildMatchReportHtml(user, natureName);
    } else if (key === 'career') {
      section.innerHTML = buildCareerReportHtml(user, natureName);
    }

    container.appendChild(section);
  });

  activeReportTab = purchasedKeys[0];
}

// 탭 전환
function switchReportTab(reportKey) {
  activeReportTab = reportKey;
  document.querySelectorAll('.report-tab-btn').forEach(btn => btn.classList.remove('active'));
  const activeBtn = document.getElementById(`repTabBtn_${reportKey}`);
  if (activeBtn) activeBtn.classList.add('active');

  document.querySelectorAll('.purchased-report-section').forEach(sec => sec.classList.remove('active'));
  const targetSec = document.getElementById(`purchasedSection_${reportKey}`);
  if (targetSec) {
    targetSec.classList.add('active');
    targetSec.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}

// ==========================================================================
// 10-2. 목판본(木版本) 사주팔자 원국 명식표(命式表) 렌더러
// ==========================================================================
function buildMyeongshikTableHtml(user) {
  const p = user.pillars;
  const dayMaster = p.day.stemIdx;
  const pattern = user.pattern || SAJU_PATTERNS['정관격'];
  const strength = user.strength || { title: '중화 사주', score: 50 };
  const yongshin = user.yongshin || { eokbuYongshin: '식상·재성', johuYongshin: '수(水)' };
  const shinsalList = user.extendedShinsal || [];
  const topShinsals = shinsalList.slice(0, 4).map(s => s.name).join(' · ') || '천을귀인 · 문창귀인';

  const pCols = [
    { key: 'hour', label: '시주 (時柱)', p: p.hour, desc: '말년 · 자녀' },
    { key: 'day', label: '일주 (日柱)', p: p.day, desc: '나자신 · 배우자' },
    { key: 'month', label: '월주 (月柱)', p: p.month, desc: '사회운 · 직업' },
    { key: 'year', label: '연주 (年柱)', p: p.year, desc: '초년운 · 조상' }
  ];

  const headerCells = pCols.map(c => `
    <th>
      <span class="col-main-label">${c.label}</span>
      <span class="col-sub-desc">${c.desc}</span>
    </th>
  `).join('');

  const stemCells = pCols.map(c => {
    if (!c.p) return `<td><div class="myeongshik-char-block empty"><span class="m-char">未時</span><span class="m-sub">시간 미입력</span></div></td>`;
    const tg = (c.key === 'day') ? '일원 (日元)' : getTenGod(dayMaster, c.p.stemIdx);
    const hanja = CHEONGAN_HANJA[c.p.stemIdx];
    const korean = CHEONGAN[c.p.stemIdx];
    const el = CHEONGAN_ELEMENTS[c.p.stemIdx];
    return `
      <td>
        <div class="myeongshik-char-block ${el}">
          <span class="m-tengod">${tg}</span>
          <span class="m-char">${hanja}</span>
          <span class="m-korean">${korean} (${ELEMENT_KOREAN[el].split(' ')[0]})</span>
        </div>
      </td>
    `;
  }).join('');

  const branchCells = pCols.map(c => {
    if (!c.p) return `<td><div class="myeongshik-char-block empty"><span class="m-char">-</span></div></td>`;
    const hiddenStem = HIDDEN_STEMS[c.p.branchIdx][0];
    const tg = getTenGod(dayMaster, hiddenStem);
    const hanja = JIJI_HANJA[c.p.branchIdx];
    const korean = JIJI[c.p.branchIdx];
    const el = JIJI_ELEMENTS[c.p.branchIdx];
    const animal = JIJI_ANIMALS[c.p.branchIdx];
    return `
      <td>
        <div class="myeongshik-char-block ${el}">
          <span class="m-tengod">${tg}</span>
          <span class="m-char">${hanja}</span>
          <span class="m-korean">${korean} (${animal} · ${ELEMENT_KOREAN[el].split(' ')[0]})</span>
        </div>
      </td>
    `;
  }).join('');

  const shinsalCells = pCols.map(c => {
    if (!c.p) return `<td><span class="m-shinsal-tag">-</span></td>`;
    const sList = extractShinsal(c.key, c.p.stemIdx, c.p.branchIdx, dayMaster, p.month.branchIdx);
    const tags = sList.slice(0, 2).map(s => `<span class="m-shinsal-pill ${s.type}">${s.name.split(' ')[0]}</span>`).join('');
    return `<td><div class="m-shinsals-wrap">${tags || '-'}</div></td>`;
  }).join('');

  return `
    <div class="myeongshik-woodblock-card">
      <div class="woodblock-inner-border">
        <div class="myeongshik-header">
          <div class="myeongshik-seal-box">
            <span class="seal-text">天門<br>鑑明</span>
          </div>
          <div class="myeongshik-title-group">
            <span class="woodblock-cert">皇室 秘傳 · 四柱八字 原局 命式表</span>
            <h3 class="myeongshik-owner">${user.name} 님 乾/坤 命式</h3>
          </div>
          <div class="myeongshik-meta-box">
            <span>생년월일: ${user.year}년 ${user.month}월 ${user.day}일</span>
            <span>출생시각: ${user.timeStr === 'unknown' ? '시간 미상' : user.timeStr}</span>
          </div>
        </div>

        <div class="myeongshik-table-wrap">
          <table class="myeongshik-table">
            <thead>
              <tr>${headerCells}</tr>
            </thead>
            <tbody>
              <tr class="row-stem">
                ${stemCells}
              </tr>
              <tr class="row-branch">
                ${branchCells}
              </tr>
              <tr class="row-shinsal">
                ${shinsalCells}
              </tr>
            </tbody>
          </table>
        </div>

        <div class="myeongshik-summary-bar">
          <div class="sum-item"><strong>格局(격국):</strong> <span class="sum-val gold">${pattern.name}</span> (${pattern.badge})</div>
          <div class="sum-item"><strong>身强/身弱:</strong> <span class="sum-val">${strength.title}</span> (원국 득령·득지 ${strength.score}점)</div>
          <div class="sum-item"><strong>調候用神:</strong> <span class="sum-val">${user.climate.seasonBadgeText}</span> [희용: ${yongshin.johuYongshin}]</div>
          <div class="sum-item"><strong>抑扶用神:</strong> <span class="sum-val">${yongshin.eokbuYongshin}</span></div>
          <div class="sum-item full"><strong>주요 깃든 신살:</strong> <span>${topShinsals}</span></div>
        </div>

        <div class="myeongshik-detail-section" style="margin-top:14px;">
          <table class="report-detail-table" style="margin:0; width:100%;">
            <thead>
              <tr>
                <th style="width:25%;">원국 분석 지표</th>
                <th>음양오행(陰陽五行) 및 천간·지지 심층 배속 판정</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td><strong>☯️ 일간(日元)의 특성</strong></td>
                <td><strong>${CHEONGAN_HANJA[dayMaster]} (${CHEONGAN[dayMaster]}토)</strong> — 만물을 품어 기르고 신용과 중후함을 미덕으로 삼는 포용의 기운입니다.</td>
              </tr>
              <tr>
                <td><strong>⚖️ 신강·신약 판정</strong></td>
                <td>원국 내 득령(得令)과 득지(得地)를 정밀 계측하여 <strong>${strength.title} (기운 충실도 ${strength.score}점)</strong>으로 분류되며, 설기(洩氣)와 극제(剋制)의 조화가 필요한 국면입니다.</td>
              </tr>
              <tr>
                <td><strong>🔮 억부·조후 용신</strong></td>
                <td>억부로는 <strong>${yongshin.eokbuYongshin}</strong>을 용(用)하여 재능을 발현하고, 조후로는 <strong>${yongshin.johuYongshin}</strong>을 취하여 뜨거운 열기를 식히고 윤택하게 적셔줍니다.</td>
              </tr>
              <tr>
                <td><strong>✨ 핵심 수호 신살</strong></td>
                <td>원국에 깃든 <strong>${topShinsals}</strong>이 삶의 위기마다 귀인의 조력을 이끌어내고 흉화를 길상으로 치환하는 방패막이가 되어줍니다.</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  `;
}

// ※ 4대 카테고리 86페이지 정밀 리포트 빌더(buildNewYearReportHtml, buildMasterReportHtml, buildMatchReportHtml, buildCareerReportHtml)는 lib/report-builders.js에 수록되어 있습니다.

// PDF 다운로드 또는 인쇄 트리거 (모바일/PC 공용)
function downloadOrPrintReport() {
  window.print();
}

// 리포트 공유하기
function shareReport() {
  const url = window.location.href;
  if (navigator.share) {
    navigator.share({
      title: `${currentAnalysisData.name}님의 천문사주 운명서 (cheonmun.life)`,
      text: '나의 사주 총운과 월별 터닝포인트 리포트가 완성되었습니다.',
      url: url
    }).catch(() => {});
  } else {
    navigator.clipboard.writeText(url).then(() => {
      alert('운명서 열람 링크가 클립보드에 복사되었습니다! 카카오톡이나 메모장에 저장해두세요.');
    }).catch(() => {
      alert('링크 복사를 지원하지 않는 브라우저입니다.');
    });
  }
}



// ==========================================================================
// 11. 100개 실구매자 리뷰 동적 렌더링 & 필터링 시스템
// ==========================================================================
let currentReviewCategory = 'all';
let currentReviewVisibleCount = 8;

function renderReviews() {
  const grid = document.getElementById('reviewsGrid');
  if (!grid) return;

  const filtered = (currentReviewCategory === 'all')
    ? REVIEWS_100
    : REVIEWS_100.filter(r => r.cat === currentReviewCategory);

  const visibleList = filtered.slice(0, currentReviewVisibleCount);

  grid.innerHTML = visibleList.map(r => `
    <div class="review-card">
      <div class="review-card-top">
        <div class="review-rating">
          <i class="fa-solid fa-star"></i><i class="fa-solid fa-star"></i><i class="fa-solid fa-star"></i><i class="fa-solid fa-star"></i><i class="fa-solid fa-star"></i>
          <span class="score">${r.score}</span>
        </div>
        <span class="review-badge"><i class="fa-solid fa-circle-check"></i> 실구매 감명</span>
      </div>
      <p class="review-text">"${r.text}"</p>
      <div class="review-author">
        <div class="author-info">
          <span class="name">${r.name} · ${r.loc.split(' ')[0]}</span>
          <span class="report-name">${r.saju} | ${r.report}</span>
        </div>
        <span class="review-date">${r.date}</span>
      </div>
    </div>
  `).join('');

  // 카운터 및 더보기 버튼 업데이트
  const countDisplay = document.getElementById('reviewCountDisplay');
  if (countDisplay) {
    countDisplay.textContent = `${Math.min(currentReviewVisibleCount, filtered.length)} / ${filtered.length}`;
  }

  const btnMore = document.getElementById('btnLoadMoreReviews');
  if (btnMore) {
    if (currentReviewVisibleCount >= filtered.length) {
      btnMore.innerHTML = `<i class="fa-solid fa-check"></i> 모든 후기를 확인하셨습니다 (${filtered.length}개)`;
      btnMore.disabled = true;
      btnMore.style.opacity = '0.6';
    } else {
      btnMore.innerHTML = `<i class="fa-solid fa-plus"></i> 실구매자 후기 더보기 (${Math.min(currentReviewVisibleCount, filtered.length)} / ${filtered.length})`;
      btnMore.disabled = false;
      btnMore.style.opacity = '1';
    }
  }
}

function filterReviews(category) {
  currentReviewCategory = category;
  currentReviewVisibleCount = 8;

  // 필터 버튼 활성화 스타일
  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.filter === category);
  });

  renderReviews();
}

function loadMoreReviews() {
  currentReviewVisibleCount += 8;
  renderReviews();
}

// 초기 로드 시 100개 리뷰 시스템 가동
document.addEventListener('DOMContentLoaded', () => {
  renderReviews();
});
renderReviews(); // 즉시 실행
